        // Build an SPD matrix reliably as A = MᵀM + n·I.
        // MᵀM is symmetric positive-semidefinite; adding n·I (n = dim) makes it
        // strictly positive-definite and diagonally dominant, so CG must converge.
        static doubleMxN BuildSPD(int dim, uint seed)
        {
            var M = GenerateOP.doubleRandomMat(dim, dim, -1f, 1f, seed, Allocator.Temp);

            // dot(M, M, transposeA:true) == Mᵀ·M
            var A = Blas.dot(M, M, true);

            for (int d = 0; d < dim; d++)
                A[d, d] += dim;

            return A;
        }

        // ---- Load-bearing primitives ------------------------------------------------

        // y += a * x : each element must become y0 + a*x0.
        void AddScaledInPlace()
        {
            int n = 16;

            var y = GenerateOP.doubleRandomVec(n, -1f, 1f, 11111, Allocator.Temp);
            var x = GenerateOP.doubleRandomVec(n, -1f, 1f, 22222, Allocator.Temp);
            double a = (double)(-0.75f);

            // Snapshot of the original y before the in-place update.
            var y0 = new doubleN(in y, Allocator.Temp);

            y.addScaledInPlace(a, x);

            double tol = Tol();
            for (int i = 0; i < n; i++)
            {
                double expected = y0[i] + a * x[i];
                Assert.IsTrue(math.abs(y[i] - expected) < tol);
            }
        }

        // y = a * y + x : each element must become a*y0 + x0.
        void ScaleAddInPlace()
        {
            int n = 16;

            var y = GenerateOP.doubleRandomVec(n, -1f, 1f, 33333, Allocator.Temp);
            var x = GenerateOP.doubleRandomVec(n, -1f, 1f, 44444, Allocator.Temp);
            double a = (double)1.5f;

            var y0 = new doubleN(in y, Allocator.Temp);

            y.scaleAddInPlace(a, x);

            double tol = Tol();
            for (int i = 0; i < n; i++)
            {
                double expected = a * y0[i] + x[i];
                Assert.IsTrue(math.abs(y[i] - expected) < tol);
            }
        }

        // ---- Solver -----------------------------------------------------------------

        // Defaults overload: SPD A, random b, x = 0 -> A·x ≈ b and converged.
        void SolveDefaults()
        {
            int dim = 12;

            var A = BuildSPD(dim, 90125);
            var b = GenerateOP.doubleRandomVec(dim, -1f, 1f, 4242, Allocator.Temp);

            var x = new doubleN(dim, Allocator.Temp); // zero initial guess

            bool ok = Krylov.cg(in A, in b, ref x);
            Assert.IsTrue(ok);

            var Ax = Blas.dot(A, x);
            var bMinusAx = new doubleN(in b, Allocator.Temp);
            doubleComp.subInPlace(bMinusAx, Ax);
            Assert.IsTrue(Analysis.isZero(bMinusAx, Tol()));
        }

        // CG solution must match the Cholesky solution on the same SPD system.
        void CrossCheckCholesky()
        {
            int dim = 11;

            var A = BuildSPD(dim, 707070);
            var b = GenerateOP.doubleRandomVec(dim, -1f, 1f, 8181, Allocator.Temp);

            // CG solve
            var xCG = new doubleN(dim, Allocator.Temp);
            bool ok = Krylov.cg(in A, in b, ref xCG);
            Assert.IsTrue(ok);

            // Cholesky solve on the same system (b overwritten with x), as the explicit two-call
            // composition.
            var bChol = new doubleN(in b, Allocator.Temp);
            var L = new doubleMxN(dim, dim, Allocator.Temp);
            DirectSolveInfo cholInfo = CHO.decomp(in A, ref L);
            if (cholInfo.Solved) cholInfo = CHO.decompSolve(ref L, ref bChol);
            bool cholOk = cholInfo.Solved;
            Assert.IsTrue(cholOk);

            var xCGMinusBChol = new doubleN(in xCG, Allocator.Temp);
            doubleComp.subInPlace(xCGMinusBChol, bChol);
            Assert.IsTrue(Analysis.isZero(xCGMinusBChol, Tol()));
        }

        // The caller-scratch primitive and the explicit maxIter/tol
        // overload must produce the same solution as the defaults overload.
        void OverloadsAgree()
        {
            int dim = 10;

            var A = BuildSPD(dim, 271828);
            var b = GenerateOP.doubleRandomVec(dim, -1f, 1f, 5151, Allocator.Temp);

            // Reference: defaults overload.
            var xDef = new doubleN(dim, Allocator.Temp);
            bool okDef = Krylov.cg(in A, in b, ref xDef);
            Assert.IsTrue(okDef);

            // Explicit maxIter/tol overload.
            var xExpl = new doubleN(dim, Allocator.Temp);
            bool okExpl = Krylov.cg(in A, in b, ref xExpl, dim, Consts.doubleSqrtEps);
            Assert.IsTrue(okExpl);
            var xDefMinusXExpl = new doubleN(in xDef, Allocator.Temp);
            doubleComp.subInPlace(xDefMinusXExpl, xExpl);
            Assert.IsTrue(Analysis.isZero(xDefMinusXExpl, Tol()));

            // Zero-alloc primitive with caller-provided scratch r, p, Ap.
            var xPrim = new doubleN(dim, Allocator.Temp);
            var r = new doubleN(dim, Allocator.Temp);
            var p = new doubleN(dim, Allocator.Temp);
            var Ap = new doubleN(dim, Allocator.Temp);
            bool okPrim = Krylov.cg(in A, in b, ref xPrim,
                                                    ref r, ref p, ref Ap,
