            Assert.IsTrue(okPrim);
            var xDefMinusXPrim = new doubleN(in xDef, Allocator.Temp);
            doubleComp.subInPlace(xDefMinusXPrim, xPrim);
            Assert.IsTrue(Analysis.isZero(xDefMinusXPrim, Tol()));
        }

